package ro.leo.visual;
import ro.leo.i18n.Language;
import android.app.*;import android.content.*;import android.os.*;import android.provider.Settings;import android.view.accessibility.AccessibilityManager;import java.util.*;
/** Visible-only UI timing and bounded repair of an already-enabled own key service. */
public final class LeoApplication extends Application implements Application.ActivityLifecycleCallbacks {
 private final Handler main=new Handler();private long due;static long worstDelay;private boolean visible;private static long lastRepair;private static boolean repairing;
 private final Runnable repair=new Runnable(){public void run(){if(visible)repairKeys(LeoApplication.this,false);}};
 private final Runnable pulse=new Runnable(){public void run(){if(!visible)return;long now=SystemClock.uptimeMillis();worstDelay=Math.max(worstDelay,Math.max(0,now-due));due=now+2000;main.postDelayed(this,2000);}};
 public void onCreate(){super.onCreate();Language.sync(this);final Thread.UncaughtExceptionHandler previous=Thread.getDefaultUncaughtExceptionHandler();Thread.setDefaultUncaughtExceptionHandler(new Thread.UncaughtExceptionHandler(){public void uncaughtException(Thread thread,Throwable failure){FaultLedger.record(LeoApplication.this,"Uncaught",failure);if(previous!=null)previous.uncaughtException(thread,failure);else android.os.Process.killProcess(android.os.Process.myPid());}});registerActivityLifecycleCallbacks(this);}
 static void repairKeys(final Context context,boolean explicit){final Context c=context.getApplicationContext();final long now=SystemClock.elapsedRealtime();if(repairing||(!explicit&&now-lastRepair<60000)||(!explicit&&LeoPointerService.connected()))return;final String component="ro.leo.visual/ro.leo.visual.LeoPointerService";String configured=Settings.Secure.getString(c.getContentResolver(),"enabled_accessibility_services");if(configured==null||(!Arrays.asList(configured.split(":")).contains(component)&&!Arrays.asList(configured.split(":")).contains("ro.leo.visual/.LeoPointerService")))return;lastRepair=now;repairing=true;try{ArrayList<String> others=new ArrayList<String>(Arrays.asList(configured.split(":")));others.remove(component);others.remove("ro.leo.visual/.LeoPointerService");Settings.Secure.putString(c.getContentResolver(),"enabled_accessibility_services",android.text.TextUtils.join(":",others));new Handler(Looper.getMainLooper()).postDelayed(new Runnable(){public void run(){try{String current=Settings.Secure.getString(c.getContentResolver(),"enabled_accessibility_services");ArrayList<String> entries=new ArrayList<String>();if(current!=null&&!current.isEmpty())entries.addAll(Arrays.asList(current.split(":")));if(!entries.contains(component))entries.add(component);Settings.Secure.putString(c.getContentResolver(),"enabled_accessibility_services",android.text.TextUtils.join(":",entries));}catch(RuntimeException denied){}finally{repairing=false;}}},300);}catch(RuntimeException denied){repairing=false;}}
 public void onActivityResumed(Activity a){visible=true;main.removeCallbacks(pulse);due=SystemClock.uptimeMillis()+2000;main.postDelayed(pulse,2000);main.removeCallbacks(repair);/* Camera lives separately; the accessibility service belongs to the launcher process. */if(!(a instanceof CameraActivity))main.postDelayed(repair,1500);}
 public void onActivityPaused(Activity a){visible=false;main.removeCallbacks(pulse);main.removeCallbacks(repair);}
 public void onActivityCreated(Activity a,Bundle b){Language.sync(a);}public void onActivityStarted(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}
}
